#include <stdio.h>
#include <string.h>

#define MAXN 100    /* 顶点数上限 */
#define MAXM 1000   /* 边数上限(无向图双向存储, 弧数最多 2*MAXM) */

int main(void) {
    int n, m, i, u, v, w;
    int mat[MAXN][MAXN];                          /* 邻接矩阵 */
    int head[MAXN], to[2 * MAXM], wt[2 * MAXM], nxt[2 * MAXM], ecnt = 0;
    /* 邻接表用链式前向星: head[u] 指向 u 的第一条弧, nxt 串联同起点的弧 */

    printf("输入顶点数 n 边数 m: ");
    scanf("%d %d", &n, &m);
    memset(mat, 0, sizeof(mat));
    for (i = 0; i < n; i++) head[i] = -1;

    printf("输入 %d 条边 (u v w, 顶点从 0 开始, 无向带权):\n", m);
    for (i = 0; i < m; i++) {
        scanf("%d %d %d", &u, &v, &w);
        mat[u][v] = mat[v][u] = w;                /* 矩阵: 无向边对称赋值 */

        to[ecnt] = v; wt[ecnt] = w; nxt[ecnt] = head[u]; head[u] = ecnt++;
        to[ecnt] = u; wt[ecnt] = w; nxt[ecnt] = head[v]; head[v] = ecnt++;
        /* 邻接表: 每条无向边存两个方向的弧, 空间约 2m */
    }

    printf("\n邻接矩阵:\n");
    for (i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) printf("%3d ", mat[i][j]);
        printf("\n");
    }

    printf("\n邻接表:\n");
    for (i = 0; i < n; i++) {
        printf("v%d:", i);
        for (int e = head[i]; e != -1; e = nxt[e])
            printf(" -> (%d, w=%d)", to[e], wt[e]);
        printf(" -> NULL\n");
    }
    return 0;
}

#include <stdio.h>
#include <string.h>

#define MAXN 1000
#define MAXM 10000   /* 无向图边数上限, 弧数最多 2*MAXM */

int main(void) {
    int n, m, s, i, u, v;
    int head[MAXN], to[2 * MAXM], nxt[2 * MAXM], ecnt = 0;
    int dist[MAXN], parent[MAXN], q[MAXN];   /* 数组模拟队列 */
    int qh = 0, qt = 0;

    printf("输入顶点数 n 边数 m 源点 s: ");
    scanf("%d %d %d", &n, &m, &s);
    memset(head, -1, sizeof(head));
    memset(dist, -1, sizeof(dist));          /* -1 表示未访问(无穷) */
    memset(parent, -1, sizeof(parent));

    printf("输入 %d 条无向无权边 (u v):\n", m);
    for (i = 0; i < m; i++) {
        scanf("%d %d", &u, &v);
        to[ecnt] = v; nxt[ecnt] = head[u]; head[u] = ecnt++;
        to[ecnt] = u; nxt[ecnt] = head[v]; head[v] = ecnt++;
    }

    /* BFS: 入队即标记, 保证每个顶点至多入队一次 O(n+m) */
    dist[s] = 0; q[qt++] = s;
    while (qh < qt) {
        u = q[qh++];                         /* 出队: 按距离非降序 */
        for (int e = head[u]; e != -1; e = nxt[e]) {
            v = to[e];
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                parent[v] = u;               /* 广度优先树的边 */
                q[qt++] = v;                 /* 入队时立即标记 */
            }
        }
    }

    printf("\n各顶点到 %d 的最短距离与路径:\n", s);
    for (v = 0; v < n; v++) {
        printf("v%d: dist = %d, 路径: ", v, dist[v]);
        if (dist[v] == -1) { printf("不可达\n"); continue; }
        int path[MAXN], len = 0, cur = v;
        while (cur != -1) { path[len++] = cur; cur = parent[cur]; }
        for (i = len - 1; i >= 0; i--) printf("%d%s", path[i], i ? " -> " : "\n");
    }
    return 0;
}

#include <stdio.h>
#include <string.h>

#define MAXN 1000
#define MAXM 10000

int main(void) {
    int n, m, i, u, v;
    int head[MAXN], to[MAXM], nxt[MAXM], ecnt = 0;
    int indeg[MAXN], q[MAXN];
    int qh = 0, qt = 0, cnt = 0;

    printf("输入顶点数 n 边数 m: ");
    scanf("%d %d", &n, &m);
    memset(head, -1, sizeof(head));
    memset(indeg, 0, sizeof(indeg));

    printf("输入 %d 条有向边 (u v, 表示 u -> v):\n", m);
    for (i = 0; i < m; i++) {
        scanf("%d %d", &u, &v);
        to[ecnt] = v; nxt[ecnt] = head[u]; head[u] = ecnt++;
        indeg[v]++;                          /* 统计入度 */
    }

    /* Kahn 算法: 反复取入度为 0 的顶点, O(n+m) */
    for (i = 0; i < n; i++)
        if (indeg[i] == 0) q[qt++] = i;

    while (qh < qt) {
        u = q[qh++];
        cnt++;
        for (int e = head[u]; e != -1; e = nxt[e]) {
            v = to[e];
            if (--indeg[v] == 0) q[qt++] = v;   /* 删边后入度归零即可入队 */
        }
    }

    if (cnt < n) { printf("图中存在环, 无法拓扑排序\n"); return 0; }
    printf("拓扑序列: ");
    for (i = 0; i < n; i++) printf("%d ", q[i]);
    printf("\n");
    return 0;
}

#include <stdio.h>
#include <string.h>

#define MAXN 1000
#define MAXM 10000

int n, m;
int head[MAXN], to[MAXM], nxt[MAXM], ecnt;         /* 原图 */
int rhead[MAXN], rto[MAXM], rnxt[MAXM], recnt;     /* 转置图 */
int vis[MAXN], order[MAXN], ocnt;                  /* 第一次 DFS 完成序 */
int comp[MAXN];                                    /* 顶点所属分量 */

void dfs1(int u) {                                 /* 原图 DFS: 记录完成时间 */
    vis[u] = 1;
    for (int e = head[u]; e != -1; e = nxt[e])
        if (!vis[to[e]]) dfs1(to[e]);
    order[ocnt++] = u;                             /* 完成后压栈 */
}

void dfs2(int u, int cid) {                        /* 转置图 DFS: 划分 SCC */
    comp[u] = cid;
    for (int e = rhead[u]; e != -1; e = rnxt[e])
        if (comp[rto[e]] == -1) dfs2(rto[e], cid);
}

int main(void) {
    int u, v, cid = 0;
    printf("输入顶点数 n 边数 m: ");
    scanf("%d %d", &n, &m);
    memset(head, -1, sizeof(head));
    memset(rhead, -1, sizeof(rhead));
    memset(comp, -1, sizeof(comp));

    printf("输入 %d 条有向边 (u v):\n", m);
    for (int i = 0; i < m; i++) {
        scanf("%d %d", &u, &v);
        to[ecnt] = v; nxt[ecnt] = head[u]; head[u] = ecnt++;
        rto[recnt] = u; rnxt[recnt] = rhead[v]; rhead[v] = recnt++;  /* 反向边 */
    }

    for (int i = 0; i < n; i++) if (!vis[i]) dfs1(i);
    for (int i = ocnt - 1; i >= 0; i--)            /* 按完成时间降序 */
        if (comp[order[i]] == -1) dfs2(order[i], cid++);

    printf("\n强连通分量个数: %d\n", cid);
    for (int i = 0; i < n; i++)
        printf("顶点 %d 属于分量 %d\n", i, comp[i]);
    return 0;
}
